insert into storage.buckets(id,name,public) values ('originals','originals',false) on conflict do nothing;
create table questions(id serial primary key, unit_id uuid references units(id), qtype text, question text not null, marks int default 1, difficulty text, answer text, created_by uuid default auth.uid());
create table assessments(id serial primary key, title text not null, kind text, unit_id uuid references units(id), total_marks int, duration_minutes int, status text default 'draft', created_by uuid default auth.uid());
create table videos(id serial primary key, title text not null, url text not null, category text, transcript text, status text default 'pending', created_by uuid default auth.uid());
create table plans(id serial primary key, name text unique not null, price_kes numeric, duration_days int, active boolean default true);
alter table questions enable row level security; alter table assessments enable row level security; alter table videos enable row level security; alter table plans enable row level security;
create policy "upload to own folder" on storage.objects for insert to authenticated with check (bucket_id='originals' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "read originals" on storage.objects for select to authenticated using (bucket_id='originals' and ((storage.foldername(name))[1]=auth.uid()::text or has_role(array['super_admin','system_admin','content_admin']) or exists(select 1 from resources r where r.original_path=name and r.status='approved' and r.access_level in ('public','free'))));
create policy "insert own resource" on resources for insert to authenticated with check (uploaded_by=auth.uid() and has_role(array['teacher','tvet_trainer','super_admin','system_admin','content_admin']));
create policy "read own resources" on resources for select to authenticated using (uploaded_by=auth.uid());
create policy "admins manage resources" on resources for all to authenticated using (has_role(array['super_admin','system_admin','content_admin'])) with check (has_role(array['super_admin','system_admin','content_admin']));
create policy "read approved resources" on resources for select to authenticated using (status='approved' and access_level in ('public','free'));
create policy "own classification read" on resource_classifications for select to authenticated using (exists(select 1 from resources r where r.id=resource_id and r.uploaded_by=auth.uid()));
create policy "own classification insert" on resource_classifications for insert to authenticated with check (exists(select 1 from resources r where r.id=resource_id and r.uploaded_by=auth.uid()));
create policy "admins manage classifications" on resource_classifications for all to authenticated using (has_role(array['super_admin','system_admin','content_admin'])) with check (has_role(array['super_admin','system_admin','content_admin']));
create policy "own questions" on questions for all to authenticated using (created_by=auth.uid() or has_role(array['super_admin','system_admin','content_admin'])) with check (has_role(array['teacher','tvet_trainer','super_admin','system_admin','content_admin']));
create policy "own assessments" on assessments for all to authenticated using (created_by=auth.uid() or has_role(array['super_admin','system_admin','content_admin'])) with check (has_role(array['teacher','tvet_trainer','super_admin','system_admin','content_admin']));
create policy "read videos" on videos for select to authenticated using (status='approved' or created_by=auth.uid() or has_role(array['super_admin','system_admin','content_admin']));
create policy "add videos" on videos for insert to authenticated with check (created_by=auth.uid() and has_role(array['teacher','tvet_trainer','super_admin','system_admin','content_admin']) and (status='pending' or has_role(array['super_admin','system_admin','content_admin'])));
create policy "admins manage videos" on videos for all to authenticated using (has_role(array['super_admin','system_admin','content_admin'])) with check (has_role(array['super_admin','system_admin','content_admin']));
create policy "read plans" on plans for select to authenticated using (true);
create policy "admins manage plans" on plans for all to authenticated using (has_role(array['super_admin','system_admin'])) with check (has_role(array['super_admin','system_admin']));
